impl Default for ChatArgs {
    fn default() -> Self {
        Self {
            prompt: None,
            session_id: None,
            new: false,
            provider: None,
            model: None,
            system_prompt: None,
            approval_required: Vec::new(),
            image: "python".to_string(),
            idle_timeout_secs: 300,
            max_turns: 20,
            poll_interval_ms: 750,
            stream_timeout_ms: 1_800_000,
            wait: false,
        }
    }
}

